"""
myCITA (My Career, Income, Target & Achievement) - myCITA Komponen Usaha
Tempel seluruh isi file ini ke Custom Component Langflow (tombol Code).
Versi 1.1.0
"""
import json
import math
import os
import re
import sqlite3
